package com.sahilm.tutorly.ui.home.screen.shorts.adapter

import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.media3.common.MediaItem
import androidx.media3.exoplayer.ExoPlayer
import androidx.recyclerview.widget.RecyclerView
import com.sahilm.tutorly.databinding.ItemShortsBinding
import com.sahilm.tutorly.domain.model.ShortVideoDomainModel

class ShortsAdapter : RecyclerView.Adapter<ShortsAdapter.ShortsViewHolder>() {

    private val items = mutableListOf<ShortVideoDomainModel>()
    private var exoPlayer: ExoPlayer? = null
    private var currentPlayerPosition = 0

    fun setExoPlayer(player: ExoPlayer) {
        this.exoPlayer = player
    }

    fun submitList(newItems: List<ShortVideoDomainModel>) {
        items.clear()
        items.addAll(newItems)
        notifyDataSetChanged()
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ShortsViewHolder {
        val binding = ItemShortsBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return ShortsViewHolder(binding)
    }

    override fun onBindViewHolder(holder: ShortsViewHolder, position: Int) {
        holder.bind(items[position])
    }

    override fun getItemCount(): Int = items.size

    inner class ShortsViewHolder(private val binding: ItemShortsBinding) :
        RecyclerView.ViewHolder(binding.root) {

        fun bind(short: ShortVideoDomainModel) {
            binding.apply {
                tvTitle.text = short.title

                playerView.player = exoPlayer

                itemView.setOnClickListener {
                    exoPlayer?.let { player ->
                        val mediaItem = MediaItem.fromUri(short.videoUrl)
                        player.setMediaItem(mediaItem)
                        if (!player.isPlaying) {
                            player.prepare()
                            player.play()
                            currentPlayerPosition = bindingAdapterPosition
                        }
                    }
                }
            }
        }
    }
}

package com.sahilm.tutorly.ui.home.screen.shorts.adapter

import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.media3.common.MediaItem
import androidx.media3.exoplayer.ExoPlayer
import androidx.recyclerview.widget.RecyclerView
import com.sahilm.tutorly.databinding.ItemShortsBinding
import com.sahilm.tutorly.domain.model.ShortVideoDomainModel

class ShortsAdapter : RecyclerView.Adapter<ShortsAdapter.ShortsViewHolder>() {

    private val items = mutableListOf<ShortVideoDomainModel>()
    private var exoPlayer: ExoPlayer? = null

    fun setExoPlayer(player: ExoPlayer) {
        this.exoPlayer = player
    }

    fun submitList(newItems: List<ShortVideoDomainModel>) {
        items.clear()
        items.addAll(newItems)
        notifyDataSetChanged()
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ShortsViewHolder {
        val binding = ItemShortsBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return ShortsViewHolder(binding)
    }

    override fun onBindViewHolder(holder: ShortsViewHolder, position: Int) {
        holder.bind(items[position])
    }

    override fun getItemCount(): Int = items.size

    override fun onViewAttachedToWindow(holder: ShortsViewHolder) {
        super.onViewAttachedToWindow(holder)
        holder.playVideo()
    }

    override fun onViewDetachedFromWindow(holder: ShortsViewHolder) {
        super.onViewDetachedFromWindow(holder)
        exoPlayer?.pause()
    }

    inner class ShortsViewHolder(private val binding: ItemShortsBinding) :
        RecyclerView.ViewHolder(binding.root) {

        fun bind(short: ShortVideoDomainModel) {
            binding.apply {
                tvTitle.text = short.title
                playerView.apply {
                    player = exoPlayer
                    showController = false
                    useController = false
                }
            }
        }

        fun playVideo() {
            exoPlayer?.let { player ->
                val short = items.getOrNull(bindingAdapterPosition) ?: return@let
                val mediaItem = MediaItem.fromUri(short.videoUrl)
                player.setMediaItem(mediaItem)
                player.prepare()
                player.play()
            }
        }
    }
}

package com.sahilm.tutorly.ui.home.screen.shorts

import android.os.Bundle
import androidx.fragment.app.Fragment
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.viewModels
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.lifecycleScope
import androidx.lifecycle.repeatOnLifecycle
import androidx.media3.exoplayer.ExoPlayer
import androidx.recyclerview.widget.LinearLayoutManager
import com.sahilm.tutorly.databinding.FragmentShortsBinding
import com.sahilm.tutorly.ui.home.screen.shorts.adapter.ShortsAdapter
import com.sahilm.tutorly.ui.home.screen.shorts.models.ShortsIntent
import dagger.hilt.android.AndroidEntryPoint
import kotlinx.coroutines.launch

@AndroidEntryPoint
class ShortsFragment : Fragment() {

    private val viewModel: ShortsViewModel by viewModels()
    private var _binding: FragmentShortsBinding? = null
    private val binding get() = _binding!!

    private val adapter = ShortsAdapter()
    private var exoPlayer: ExoPlayer? = null

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentShortsBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        setupExoPlayer()
        setupRecyclerView()
        observeViewState()
    }

    private fun setupExoPlayer() {
        exoPlayer = ExoPlayer.Builder(requireContext()).build().apply {
            adapter.setExoPlayer(this)
        }
    }

    private fun setupRecyclerView() {
        binding.rvShorts.apply {
            adapter = this@ShortsFragment.adapter
            layoutManager = LinearLayoutManager(requireContext())
        }
    }

    private fun observeViewState() {
        viewLifecycleOwner.lifecycleScope.launch {
            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
                viewModel.viewState.collect { state ->
                    adapter.submitList(state.shorts)
                }
            }
        }
    }

    override fun onPause() {
        super.onPause()
        exoPlayer?.pause()
    }

    override fun onResume() {
        super.onResume()
        exoPlayer?.play()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        exoPlayer?.release()
        exoPlayer = null
        _binding = null
    }

    companion object {
        fun newInstance() = ShortsFragment()
    }
}

